 if(startupWidget){startupWidget=false;if(!document.body.classList.contains('compact'))await $('compact').onclick();}if(liveWaiting&&selected.length>=(mode==='battle'?2:1)){if(mode==='dungeon')start({focus:false});else{liveWaiting=false;prepareWidgetGame();}}
